import org.apache.commons.lang3.tuple.ImmutablePair;

public class FrameStack {
    private List<ImmutablePair<String, Integer>> stack;

    public FrameStack() {
        stack = new ArrayList<>();
    }

    public int pop() {
        if (stack.isEmpty()) {
            throw new EmptyStackException();
        }
        ImmutablePair<String, Integer> pair = stack.remove(stack.size() - 1);
        return pair.getValue1();
    }

    public void push(String type, int value) {
        stack.add(new ImmutablePair<>(type, value));
    }

    public static void main(String[] args) {
        FrameStack frameStack = new FrameStack();
        frameStack.push("int", 42);
        int value = frameStack.pop();
        System.out.println("Popped value: " + value);
    }
}
