import java.nio.ByteBuffer;

/**
 * Decodes octets to characters using the UTF-8 decoding and appends the characters to a StringBuffer.
 * @return the index to the next unchecked character in the string to decode
 */
private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int length = bb.remaining();
    while (i < length && bb.hasRemaining()) {
        int b = bb.get();
        if ((b & 0x80) == 0) {
            // Single-byte character
            sb.append((char) b);
        } else if ((b & 0xE0) == 0xC0) {
            // Two-byte character
            int b2 = bb.get();
            int codePoint = ((b & 0x1F) << 6) | (b2 & 0x3F);
            sb.append((char) codePoint);
        } else if ((b & 0xF0) == 0xE0) {
            // Three-byte character
            int b2 = bb.get();
            int b3 = bb.get();
            int codePoint = ((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
            sb.append((char) codePoint);
        } else if ((b & 0xF8) == 0xF0) {
            // Four-byte character
            int b2 = bb.get();
            int b3 = bb.get();
            int b4 = bb.get();
            int codePoint = ((b & 0x07) << 18) | ((b2 & 0x3F) << 12) | ((b3 & 0x3F) << 6) | (b4 & 0x3F);
            sb.append((char) codePoint);
        }
        i++;
    }
    return i;
}
