     * @param data to be added potentially.
     */
    @Override
    public void accept(final METRICS data) {
        if (cache.containsKey(data.getId())) {
            METRICS existingData = cache.get(data.getId());
            existingData.merge(data);
        } else {
            cache.put(data.getId(), data);
