public void insertBefore(Bucket bucket) {
    if (bucket == null) {
        throw new IllegalArgumentException("Bucket cannot be null");
    }
    if (this.prev == null) {
        // If this bucket is the head, set the previous bucket as the head's previous
        this.prev = bucket;
        bucket.next = this;
    } else {
        // Insert the bucket before this bucket
        bucket.prev = this.prev;
        this.prev.next = bucket;
        bucket.next = this;
        this.prev = bucket;
    }
}
