import java.util.Stack;

private void pop(final String descriptor) {
    Stack<String> outputFrameStack = new Stack<>();
    // Assuming the outputFrameStack is populated somewhere else in the code

    int count = 0;
    int i = 0;
    while (i < descriptor.length()) {
        char c = descriptor.charAt(i);
        if (c == 'L') {
            // Skip the class name (until ';')
            while (descriptor.charAt(i) != ';') {
                i++;
            }
            i++;
        } else if (c == '[') {
            // Skip the array descriptor
            while (descriptor.charAt(i) == '[') {
                i++;
            }
            // Handle the element descriptor
            if (descriptor.charAt(i) == 'L') {
                while (descriptor.charAt(i) != ';') {
                    i++;
                }
                i++;
            } else {
                i++;
            }
        } else {
            i++;
        }
        count++;
    }

    while (count > 0) {
        if (!outputFrameStack.isEmpty()) {
            outputFrameStack.pop();
        }
        count--;
    }
}
