public void readFrom(final InputStream in) throws IOException {
    byte[] buffer = new byte[4096]; // Adjust buffer size as needed
    int bytesRead;
    int offset = 0;

    while ((bytesRead = in.read(buffer, offset, buffer.length - offset)) != -1) {
        offset += bytesRead;
        if (offset == buffer.length) {
            // Buffer is full, create a new larger buffer and copy data
            byte[] newBuffer = new byte[buffer.length * 2];
            System.arraycopy(buffer, 0, newBuffer, 0, offset);
            buffer = newBuffer;
        }
    }

    // Resize buffer to actual data size
    byte[] resizedBuffer = new byte[offset];
    System.arraycopy(buffer, 0, resizedBuffer, 0, offset);
    // Reset to the start of the buffer
    // (Assuming a field called 'data' holds the buffer)
    this.data = resizedBuffer;
