import java.io.IOException;

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int l = str.length();
    int i = 0;
    while (i < l) {
        char c = str.charAt(i);
        if (c == '\\') {
            i++;
            if (i == l) {
                throw new IOException("Trailing backslash");
            }
            c = str.charAt(i);
            switch (c) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '"':
                    sb.append('"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                default:
                    throw new IOException("Unsupported escape character: " + c);
            }
        } else {
            sb.append(c);
        }
        i++;
    }
    return sb.toString();
}
