    /** 
     * <p> Registers the given object. Used by the reflection methods to avoid infinite loops. </p>
     * @param value The object to register.
     */
    public static void register(Object value) {
        synchronized (registeredObjects) {
            if (!registeredObjects.contains(value)) {
                registeredObjects.add(value);
            }
        }
    }

    /** 
     * <p> Unregisters the given object. </p>
     * @param value The object to unregister.
     */
    public static void unregister(Object value) {
        synchronized (registeredObjects) {
            registeredObjects.remove(value);
        }
    }

    /** 
     * <p> Checks if the given object is registered. </p>
     * @param value The object to check.
     * @return true if the object is registered, false otherwise.
     */
    public static boolean isRegistered(Object value) {
        synchronized (registeredObjects) {
            return registeredObjects.contains(value);
        }
    }
}
