import org.jgrapht.nio.GraphImporter;
import org.jgrapht.nio.dot.DOTImporter;
import org.jgrapht.traverse.GraphPathIterator;
import org.jgrapht.util.Pair;

import java.util.HashSet;
import java.util.Set;

// adaptations to requested method
public class GraphUtils {
    /** 
 * Transform from a Set representation to a graph path.
 * @param tour a set containing the edges of the tour
 * @param graph the graph
 * @return a graph path
 */
protected static <V, E> GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour.isEmpty()) {
        return null;
    }

    V startVertex = null;
    for (V vertex : graph.vertexSet()) {
        if (tour.stream().anyMatch(edge -> edge.getSource().equals(vertex) || edge.getTarget().equals(vertex))) {
            startVertex = vertex;
            break;
        }
    }

    if (startVertex == null) {
        return null;
    }

    Set<E> remainingEdges = new HashSet<>(tour);
    GraphPath<V, E> path = new SimpleGraph<>(new DefaultGraphTypeirected()).createPath(startVertex);

    while (!remainingEdges.isEmpty()) {
        E nextEdge = null;
        for (E edge : remainingEdges) {
            if (path.getVertexList().contains(edge.getSource())) {
                nextEdge = edge;
                break;
            }
        }

        if (nextEdge == null) {
            break;
        }

        path.addVertex(nextEdge.getTarget());
        path.addEdges(Set.of(nextEdge));
        remainingEdges.remove(nextEdge);
    }

    return path;
}
}
