import java.util.*;
import org.javatuples.Pair;

public class GraphSeparator {

    private List<Pair<List<Pair<Integer, Integer>>, Object>> computeGlobalSeparatorList(Graph graph) {
        List<Pair<List<Pair<Integer, Integer>>, Object>> globalSeparators = new ArrayList<>();

        for (Edge edge : graph.getEdges()) {
            List<Pair<Integer, Integer>> localSeparators = computeLocalSeparators(graph, edge);
            globalSeparators.add(Pair.with(localSeparators, edge));
        }

        return globalSeparators;
    }

    private List<Pair<Integer, Integer>> computeLocalSeparators(Graph graph, Edge edge) {
        List<Pair<Integer, Integer>> separators = new ArrayList<>();
        Vertex start = edge.getStart();
        Vertex end = edge.getEnd();

        Set<Vertex> startNeighbors = graph.getNeighbors(start);
        Set<Vertex> endNeighbors = graph.getNeighbors(end);

        startNeighbors.remove(start);
        endNeighbors.remove(end);

        startNeighbors.retainAll(endNeighbors);

        for (Vertex vertex : startNeighbors) {
            separators.add(Pair.with(vertex.getId(), vertex.getId()));
        }

        return separators;
    }
}
