import static org.objectweb.asm.Opcodes.*;

private void pop(final String descriptor) {
    for (char c : descriptor.toCharArray()) {
        switch (c) {
            case 'B': case 'C': case 'D': case 'F': case 'I': case 'S': case 'Z':
                // Pop one value of the given type
                visitInsn(POP);
                break;
            case 'J': case 'D':
                // Pop two values (long or double)
                visitInsn(POP2);
                break;
            case '[':
                // Pop the array reference
                visitInsn(POP);
                break;
            case 'L':
                // Find the semicolon to determine the full class name
                int semicolonIndex = descriptor.indexOf(';', descriptor.indexOf('L') + 1) + 1;
                String className = descriptor.substring(descriptor.indexOf('L') + 1, semicolonIndex);
                // Pop the object reference
                visitInsn(POP);
                break;
            default:
                // Unknown type descriptor
                throw new IllegalArgumentException("Unknown descriptor type: " + c);
        }
    }
}
