    int length = filename.length();
    if (length == 0) {
        return -1;
    }
    if (filename.indexOf('/') != -1 || filename.indexOf('\\') != -1) {
        return Math.max(filename.lastIndexOf('/'), filename.lastIndexOf('\\'));
    } else {
        return -1;
    }
}
