public class ClientAppender extends AppenderSkeleton {
    private List<Client> connectedClients = new ArrayList<>();

    public void addClient(Client client) {
        connectedClients.add(client);
    }

    @Override
    protected void append(LoggingEvent event) {
        for (Client client : connectedClients) {
            try {
                client.sendMessage(event.getMessage().toString());
            } catch (IOException e) {
                errorHandler.error("Failed to send log message to client: " + client, e, ErrorCode.WRITE_FAILURE, event);
            }
        }
    }

    @Override
    public void close() {
        // Close all connected clients
        for (Client client : connectedClients) {
            try {
                client.close();
            } catch (IOException e) {
                errorHandler.error("Failed to close client: " + client, e, ErrorCode.CLOSE_FAILURE, null);
            }
        }
        connectedClients.clear();
    }

